const ng_driver_t *ng_driver_find(const char *name)
{
    int lo = 0, hi = ng_n_drivers - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int c = strcmp(name, ng_drivers[mid].name);
        if (c == 0) return &ng_drivers[mid];
        if (c < 0) hi = mid - 1; else lo = mid + 1;
    }
    return 0;
}
